// The app accesses this namespace with a computed key only known at
// runtime; a sound analyzer must retain every export.
export function first(n) {
  const base = Number.isFinite(n) ? Math.trunc(n) : 0;
  const digits = Math.abs(base).toString().split('').map(Number);
  let checksum = 0;
  for (let i = 0; i < digits.length; i += 1) {
    checksum += digits[i] * (i + 1);
  }
  const parity = checksum % 2 === 0 ? 'even' : 'odd';
  return `first(${base}):${checksum}:${parity}`;
}

export function second(n) {
  const base = Number.isFinite(n) ? Math.trunc(n) : 0;
  const seq = [];
  let cursor = Math.abs(base) || 1;
  while (cursor > 1 && seq.length < 32) {
    seq.push(cursor);
    cursor = cursor % 2 === 0 ? cursor / 2 : cursor * 3 + 1;
  }
  seq.push(cursor);
  return `second(${base}):len=${seq.length}:last=${seq[seq.length - 1]}`;
}
